import React, { useState, useContext } from 'react';
import Form from '@rjsf/core';
import validator from '@rjsf/validator-ajv8';
import axios from 'axios';
import { Web3Context } from '../contexts/Web3Context';
import { UIContext } from '../App'; // Import UI Context

// ... (Giữ nguyên schema và uiSchema cũ) ...
const schema = {
  title: " ", // Để trống title mặc định để tự custom
  type: "object",
  required: ["topic", "question_content", "correct_option_index"],
  properties: {
    topic: { type: "string", title: "Chủ đề", enum: ["Grammar", "Vocabulary", "Reading"] },
    question_content: { type: "string", title: "Câu hỏi" },
    options: { type: "array", title: "4 Đáp án", minItems: 4, maxItems: 4, items: { type: "string" } },
    correct_option_index: { type: "integer", title: "Đáp án đúng (0-3)", enum: [0, 1, 2, 3] },
    stake_amount: { type: "integer", title: "Cược (Token)", default: 5 }
  }
};

const CreatorStudio = () => {
  const { currentAccount } = useContext(Web3Context);
  const { showToast } = useContext(UIContext); // Lấy hàm showToast
  const [loading, setLoading] = useState(false);

  const onSubmit = async ({ formData }) => {
    if (!currentAccount) return showToast('error', "Vui lòng kết nối ví trước!");
    
    setLoading(true);
    try {
      const res = await axios.post('http://localhost:5000/api/exercises/create', {
        ...formData,
        creator_address: currentAccount
      });
      
      // Sử dụng Toast đẹp thay vì alert
      showToast('success', "Bài tập đã được lưu lên IPFS thành công!");
      console.log(res.data);
    } catch (err) {
      showToast('error', "Lỗi: " + err.message);
    }
    setLoading(false);
  };

  return (
    <div className="max-w-4xl mx-auto py-10 animate-fade-in-up">
      <div className="glass-panel p-8 md:p-12 relative overflow-hidden">
        {/* Decorative Circle */}
        <div className="absolute -top-10 -right-10 w-40 h-40 bg-purple-400 rounded-full mix-blend-multiply filter blur-2xl opacity-30 animate-blob"></div>
        <div className="absolute -bottom-10 -left-10 w-40 h-40 bg-blue-400 rounded-full mix-blend-multiply filter blur-2xl opacity-30 animate-blob animation-delay-2000"></div>

        <div className="text-center mb-10 relative z-10">
          <h2 className="text-4xl font-extrabold text-gray-800 mb-2">
            Creator <span className="text-gradient">Studio</span>
          </h2>
          <p className="text-gray-500">Đóng góp tri thức - Nhận thưởng xứng đáng</p>
        </div>

        <div className="relative z-10">
          <Form 
            schema={schema} 
            validator={validator} 
            onSubmit={onSubmit}
            className="space-y-4"
          >
            <div className="mt-8">
              <button 
                type="submit" 
                disabled={loading}
                className="btn-gradient w-full py-4 text-lg flex justify-center items-center gap-3"
              >
                {loading ? <div className="spinner"></div> : "🚀 Đăng bài lên Web3"}
              </button>
            </div>
          </Form>
        </div>
      </div>
    </div>
  );
};

export default CreatorStudio;
